SELECT product_part_sign as productPartSign,
       model             as model,
       primary_key       as productPartCode,
       unity_no          as unityNo,
       delete_flag       as deleteFlag
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
  AND primary_key = #{productPartCode}

SELECT id, state, enterprise_code, product_part_type, enter_time, pcs, remark, creator, version, sync_status, attribute, quality_code_list::BIGINT[], warehouse_person, update_count, files::BIGINT[], default_route, contact_person, model, whether_test, standard, product_part_sign, dynamic_sort, primary_key productPartCode, create_time, update_time, delete_flag FROM ${productPartTableName} WHERE enterprise_code = #{enterpriseCode} AND delete_flag = 'f'
AND model IN
#{item}

